alter table pk_user add column account_type varchar(255) not null default 'GUEST';
alter table pk_user add column upgraded_at bigint not null default 0;
alter table pk_user add column avatar_value varchar(255) not null default 'avatar_1';
alter table pk_user add column legacy_auth_disabled boolean not null default false;
alter table pk_user add column delete_requested_at bigint not null default 0;
alter table pk_user add column delete_after bigint not null default 0;
create table pk_identity (id bigint generated by default as identity primary key, user_id bigint not null unique references pk_user(id), email varchar(255) unique, password_hash varchar(255), installation_id varchar(255) unique, guest_secret_hash varchar(255), email_verified boolean not null);
create table pk_device (id varchar(255) primary key, user_id bigint not null references pk_user(id), installation_id varchar(255) not null, device_name varchar(255) not null, last_active_at bigint not null, constraint uk_device_install unique(user_id, installation_id));
create table pk_session (id varchar(255) primary key, user_id bigint not null references pk_user(id), device_id varchar(255) not null references pk_device(id), access_hash varchar(255) not null unique, access_expires_at bigint not null, refresh_expires_at bigint not null, revoked boolean not null, created_at bigint not null);
create table pk_refresh (id varchar(255) primary key, session_id varchar(255) not null references pk_session(id), used boolean not null);
create table pk_verification (id varchar(255) primary key, user_id bigint not null, email varchar(255) not null, purpose varchar(255) not null, code_hash varchar(255) not null, expires_at bigint not null, attempts integer not null, consumed boolean not null);
create table pk_account_audit (id bigint generated by default as identity primary key, user_id bigint not null, action varchar(255) not null, created_at bigint not null);
create index ix_session_user on pk_session(user_id);
create index ix_verification_lookup on pk_verification(email,purpose,user_id);
